using System.Diagnostics;
namespace WirePulse;

public sealed record SpectrumFrame(double[] Bands, double[] Low, double[] High, int SampleRate, int FftSize, double PeakHz, long Frames, double Age);
public sealed class Spectrum
{
    readonly object sync = new(); int n, rate, cursor, hop; double[] left = [], right = [], win = [], re = [], im = [], power = []; int[] starts = [], ends = []; double sum; long frames; double last; SpectrumFrame published = new(new double[64], new double[64], new double[64], 0, 0, 0, 0, 999);
    public void Configure(int sampleRate) { if (rate == sampleRate) return; if (sampleRate < 8000 || sampleRate > 768000) throw new ArgumentOutOfRangeException(nameof(sampleRate)); rate = sampleRate; n = 8192; while (n < rate / 6d && n < 65536) n *= 2; left = new double[n]; right = new double[n]; win = new double[n]; re = new double[n]; im = new double[n]; power = new double[n / 2 + 1]; sum = 0; for (int i = 0; i < n; i++) { win[i] = .5 - .5 * Math.Cos(2 * Math.PI * i / n); sum += win[i]; } cursor = hop = 0; starts = new int[64]; ends = new int[64]; ends[0] = 1; int boundary = 1; for (int b = 0; b < 63; b++) { int end = b == 62 ? n / 2 + 1 : Math.Max(boundary + 1, Math.Min(n / 2 + 1 - (62 - b), (int)Math.Round(Math.Pow(n / 2 + 1, (b + 1) / 63d)))); starts[b + 1] = boundary; ends[b + 1] = end; boundary = end; } }
    public void Push(float[] data, int samples, int channels, int sampleRate) { Configure(sampleRate); for (int f = 0; f < samples / channels; f++) { left[cursor] = float.IsFinite(data[f * channels]) ? data[f * channels] : 0; right[cursor] = channels > 1 ? (float.IsFinite(data[f * channels + 1]) ? data[f * channels + 1] : 0) : left[cursor]; cursor = (cursor + 1) % n; if (++hop >= Math.Max(1, rate / 60)) { hop = 0; Analyze(); } } }
    void Analyze()
    {
        Array.Clear(power); for (int ch = 0; ch < 2; ch++) { var ring = ch == 0 ? left : right; for (int i = 0; i < n; i++) { re[i] = ring[(cursor + i) % n] * win[i]; im[i] = 0; } Fft(re, im); for (int k = 0; k <= n / 2; k++) { double scale = (k == 0 || k == n / 2 ? 1 : 2) / sum; power[k] += (re[k] * re[k] + im[k] * im[k]) * scale * scale * .5; } }
        var bands = new double[64]; var lo = new double[64]; var hi = new double[64]; for (int b = 0; b < 64; b++) { double v = 0; for (int k = starts[b]; k < ends[b]; k++) v += power[k]; v = Math.Sqrt(v / (ends[b] - starts[b])); bands[b] = Math.Clamp((20 * Math.Log10(Math.Max(1e-7, v)) + 72) / 60, 0, 1); lo[b] = b == 0 ? 0 : (starts[b] - .5) * rate / n; hi[b] = Math.Min(rate / 2d, (ends[b] - .5) * rate / n); }
        int peak = 0; for (int k = 1; k < power.Length; k++) if (power[k] > power[peak]) peak = k; lock (sync) { last = Stopwatch.GetTimestamp() / (double)Stopwatch.Frequency; published = new(bands, lo, hi, rate, n, peak * (double)rate / n, ++frames, 0); }
    }
    public SpectrumFrame Snapshot() { lock (sync) return published with { Age = Stopwatch.GetTimestamp() / (double)Stopwatch.Frequency - last }; }
    static void Fft(double[] re, double[] im) { int n = re.Length; for (int i = 1, j = 0; i < n; i++) { int bit = n >> 1; for (; (j & bit) != 0; bit >>= 1) j ^= bit; j ^= bit; if (i < j) { (re[i], re[j]) = (re[j], re[i]); (im[i], im[j]) = (im[j], im[i]); } } for (int len = 2; len <= n; len <<= 1) { double a = -2 * Math.PI / len, wr0 = Math.Cos(a), wi0 = Math.Sin(a); for (int i = 0; i < n; i += len) { double wr = 1, wi = 0; for (int j = 0; j < len / 2; j++) { int u = i + j, v = u + len / 2; double tr = wr * re[v] - wi * im[v], ti = wr * im[v] + wi * re[v]; re[v] = re[u] - tr; im[v] = im[u] - ti; re[u] += tr; im[u] += ti; double next = wr * wr0 - wi * wi0; wi = wr * wi0 + wi * wr0; wr = next; } } } }
}
